function init() {
  let canvas = document.getElementById('racingCanvas');
  canvas.width = canvas.height = 500;
  let c = canvas.getContext('2d'), i=0;

  try {
    micStream = await navigator.mediaDevices.getUserMedia({audio: true});
    analyser = audioContext.createAnalyser();
    analyser.fftSize = 2048;
    micStream.connect(analyser);
    animate();
    microphonePermission = true;
  } catch (err) {
    alert('Microphone access denied.');
  }
  microphoneStream = micStream.connect(analyser);

  c.font = "30px Arial";
  c.fillText("Race to the Finish!",100,50);
  c.fillText("Press SPACE to go, press M to mute/unmute mic",100,100);

  trackData = `
    11111
    1   1 
    1   1
    1   1
    11   y1111 
    1       1
    .       1
    1   u   1 
    .   p   .
    1   p   1
    1       1
    111111111111111111
    `;
  // y=finish line, u=up curb, p=down curb 

  chart = document.getElementById('chart');
  window.requestAnimationFrame(getDataForChart);
  lapTimer = document.getElementById('lapTimer');
  document.getElementById('bestLap').textContent = 'Best Lap: N/A';
}

