  setTimeout(() => lapTimer.textContent = 0, 50);
}
function getDataForChart() {
  var array = new Uint8Array(analyser.frequencyBinCount);
  analyser.getByteFrequencyData(array);
  let volume = array.reduce((a,e) => a+e,0)*0.4;
  if (microphonePermission && microphoneStream) getDataForChart();

  document.getElementById('chart').getContext('2d').clearRect(0,0,50,50);
  document.getElementById('chart').getContext('2d').beginPath();
  document.getElementById('chart').getContext('2d').arc(25,25,volume,0,2*Math.PI); //arc(x,y,radius,start,stop)
  document.getElementById('chart').getContext('2d').lineTo(25,25);
  document.getElementById('chart').getContext('2d').fill();

  return;
}
function animate() {
