  } else {
    carSpeed *= 0.95;
  }

  c.save();
  c.translate(carPos[0], carPos[1]);
  c.rotate(carAngle);
  c.fillStyle = 'brown';
  c.fillRect(0, -5, 10, 10);
  c.restore();

  carPos[0] += Math.sin(carAngle);
