    }
    carAngle = Math.atan2(Math.sin(carAngle),Math.cos(carAngle)) + (carSpeed/100);
    carPos[0] = (carPos[0]+100)%50 - 49.5;
    if (carPos[0] > 100) carPos[0] = 0;
    carPos[1] = Math.max(0,Math.min(500,carPos[1]-carSpeed));

