function checkIntersection(Objects,track) {
  // check if collision with a track object
  let i, j, x1, y1, x2, y2, i1, j1, i2, j2, obj;
  for (i=0; i<Objects.length; i++) {
    obj = Objects[i];
    x1 = obj[0];
    y1 = obj[1];
    x2 = x1+10;
    y2 = y1+10;
    for (j=0; j<track.length; j++) {
      if (track[j] !== 0) {
        i1 = Math.floor(j/track.length);
        j1 = j%track.length;
        i2 = i1+1;
        j2 = j1+1;
        if (i1>i2) {i1+=i2;i2=i1-i2;i1-=i2;}
